// The main issue is that we cannot index a `String` directly with a `usize` because it is not a slice of bytes.
// We need to convert the string to a vector of characters (or bytes) to index it safely.
    let mut s = string.clone();
    let mut i = 0;
    let mut j = s.len() - 1;
    // Find the longest palindromic suffix
    while i < j {
        if s.chars().nth(i) != s.chars().nth(j) {
            // Not a palindrome, move the left pointer forward
            i += 1;
        } else {
            // Characters match, move both pointers
            i += 1;
            j -= 1;
        }
    }
    // At this point, i and j have crossed or are at the same position.
    // The palindromic suffix starts at index i (or j+1?).
    // The palindromic suffix is s[i..] (or s[j+1..]).
    // The prefix to reverse is s[..i] (or s[..j+1]).
    // We need to reverse the prefix and append it to the end of the string.
    // However, we need to be careful about the indices.
    // Let's compute the start index of the palindromic suffix.
    // The palindromic suffix starts at index i (the left pointer after the loop).
    // The prefix to reverse is s[..i] (the part before the palindromic suffix).
    // We need to reverse the prefix and append it to the end of the string.
    // But we need to be careful about the indices because we are using a String.
    // We can convert the string to a vector of characters, manipulate it, and then convert back to a String.
    // However, we can also work directly with the String using slicing, but we need to be careful about byte indices.
    // Let's convert to a vector of characters for easier manipulation.
    let chars: Vec<char> = s.chars().collect();
    let n = chars.len();
    // Find the longest palindromic suffix
    let mut start = 0;
    for i in 0..n {
        // Check if the suffix starting at i is a palindrome
        let mut is_pal = true;
        let mut left = i;
        let mut right = n - 1;
        while left < right {
            if chars[left] != chars[right] {
                is_pal = false;
                break;
            }
            left += 1;
            right -= 1;
        }
        if is_pal {
            start = i;
            break;
        }
    }
    // The palindromic suffix starts at index `start`
    // The prefix to reverse is chars[0..start]
    // Reverse the prefix and append it to the end of the string
    let mut prefix = chars[0..start].to_vec();
    prefix.reverse();
    // Append the reversed prefix to the original string
    let mut result_chars = chars.clone();
    result_chars.extend(prefix);
    // Convert back to a String
    result_chars.iter().collect()

