let tokens: Vec<&str> = music_string.split_whitespace().collect();

// Initialize a vector to store the beats for each note
let mut beats: Vec<isize> = Vec::new();

// Define a hashmap to map note strings to their beat values
let mut note_to_beats = std::collections::HashMap::new();
note_to_beats.insert("o".to_string(), 4);
note_to_beats.insert("o|".to_string(), 2);
note_to_beats.insert(".|".to_string(), 1);

// Iterate over each token and convert it to beats
for token in tokens {
    // If the token is not found in the map, we assume it's a rest (0 beats)
    // and we skip it (continue) to avoid adding a 0 to the output vector.
    // This matches the expected behavior where rests are not represented in the output.
    if let Some(&beats_val) = note_to_beats.get(token) {
        beats.push(beats_val);
    } else {
        // Rest or unknown token: skip it
        continue;
    }
}

